#!/usr/bin/env bash
# Build the React app with the deployed API URL and upload it to S3.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
TF="terraform -chdir=$ROOT/terraform"

API_URL="$($TF output -raw api_url)"
BUCKET="$($TF output -raw frontend_bucket)"
REGION="$($TF output -raw region)"
CF_ID="$($TF output -raw cloudfront_distribution_id)"

cat > "$ROOT/frontend/.env.production.local" <<ENV
# Generated by scripts/deploy-frontend.sh - non-secret configuration only.
VITE_API_BASE_URL=$API_URL
VITE_APP_ENV=aws
ENV

cd "$ROOT/frontend"
if [[ -f package-lock.json ]]; then npm ci; else npm install; fi
npm run build

# Long cache for fingerprinted assets, no cache for index.html.
aws s3 sync dist/ "s3://$BUCKET/" --delete --region "$REGION" \
  --exclude index.html --cache-control "public,max-age=31536000,immutable"
aws s3 cp dist/index.html "s3://$BUCKET/index.html" --region "$REGION" \
  --cache-control "no-cache" --content-type "text/html"

if [[ -n "$CF_ID" ]]; then
  aws cloudfront create-invalidation --distribution-id "$CF_ID" --paths "/index.html" >/dev/null
fi
echo "Frontend uploaded: $($TF output -raw frontend_url)"
